const boardAtlasTopicSets={bones:anatomyTopics,bones2:bones2Topics,bones3:bones3Topics,bones4:bones4Topics};
for(const update of boardAtlasUpdates){const topics=boardAtlasTopicSets[update.chapter];topics.splice(1,0,update.atlas);for(const item of update.additions){const topic=topics.find(t=>t.id===item.topic);if(!topic)throw new Error("Missing redraw topic: "+item.topic);topic.sections.push(item.section);}}
